class KuramotoInteractiveApp:
    def __init__(self, n_oscillators=90, gamma=0.0, omega_0=1.0, k_over_w0=0.8, w0_tau=0.0, dt=0.005):
        self.n = int(n_oscillators)
        self.gamma = float(gamma)
        self.omega_0 = float(omega_0)
        self.k_over_w0 = float(k_over_w0)
        self.w0_tau = float(w0_tau)
        self.dt = float(dt)

        # Grandeurs physiques déduites
        self.k = self.k_over_w0 * self.omega_0
        self.tau = (self.w0_tau / self.omega_0) if self.omega_0 > 1e-5 else 0.0

        self.is_running = True
        self.time = 0.0
        self.r = 0.0

        # Synchronisation stricte sur l'horloge temps réel
        self.last_real_time = None
        self.time_accumulator = 0.0

        # Modes de clusters et bande angulaire initiale
        self.cluster_modes = ['2 Clusters', '3 Clusters', '1 Cluster', 'Aléatoire']
        self.cluster_idx = 0  # Démarrage direct en 2 Clusters pour observer plusieurs pics francs
        self.cluster_band = 0.35  # Largeur de la petite bande angulaire pour les clusters (~20°)

        # Historique glissant pour le tracé de r(t) (32 s à dt=0.005 => 8000 points)
        self.history_len = 8000
        self.time_history = deque(maxlen=self.history_len)
        self.r_history = deque(maxlen=self.history_len)

        # Initialisation de la physique et du buffer circulaire de retard
        self._init_physics()

        # Configuration de l'interface graphique
        self._init_gui()

    def _apply_cluster_phases(self):
        """Initialise les phases selon le mode de cluster sélectionné, réparties sur une petite bande angulaire."""
        band = self.cluster_band  # Largeur de la petite bande angulaire (~20° ou 0.35 rad)
        mode = self.cluster_modes[self.cluster_idx]
        if mode == '2 Clusters':
            self.phi = np.zeros(self.n, dtype=np.float64)
            n1 = self.n // 2
            self.phi[:n1] = np.random.uniform(-band / 2.0, band / 2.0, n1)
            self.phi[n1:] = np.pi + np.random.uniform(-band / 2.0, band / 2.0, self.n - n1)
        elif mode == '3 Clusters':
            self.phi = np.zeros(self.n, dtype=np.float64)
            c_size = self.n // 3
            self.phi[:c_size] = np.random.uniform(-band / 2.0, band / 2.0, c_size)
            self.phi[c_size:2 * c_size] = (2.0 * np.pi / 3.0) + np.random.uniform(-band / 2.0, band / 2.0, c_size)
            self.phi[2 * c_size:] = (4.0 * np.pi / 3.0) + np.random.uniform(-band / 2.0, band / 2.0, self.n - 2 * c_size)
        elif mode == '1 Cluster':
            self.phi = np.random.uniform(-band / 2.0, band / 2.0, self.n)
        else:  # 'Aléatoire'
            self.phi = np.random.uniform(-np.pi, np.pi, self.n)

        self.phi = (self.phi + np.pi) % (2.0 * np.pi) - np.pi

    def compute_phase_reference(self):
        """
        Calcule la référence de phase et les paramètres d'ordre généralisés (Daido) :
        - r1 : cohérence globale (1 cluster)
        - r2 : cohérence bipolaire (2 clusters en opposition de phase)
        - r3 : cohérence tripolaire (3 clusters à 120°)
        """
        z1 = np.mean(np.exp(1j * self.phi))
        r1 = float(np.abs(z1))

        z2 = np.mean(np.exp(2j * self.phi))
        r2 = float(np.abs(z2))

        z3 = np.mean(np.exp(3j * self.phi))
        r3 = float(np.abs(z3))

        if r1 >= 0.35:
            psi_ref = float(np.angle(z1))
            state_type = "1 Cluster"
        elif r2 >= 0.4:
            # Centrage symétrique pour afficher les 2 pics à -pi/2 et +pi/2
            psi_ref = float(0.5 * np.angle(z2) + 0.5 * np.pi)
            state_type = "2 Clusters"
        elif r3 >= 0.4:
            # Centrage pour afficher 1 pic central à 0 et 2 pics à +/- 2pi/3
            psi_ref = float((1.0 / 3.0) * np.angle(z3))
            state_type = "3 Clusters"
        else:
            psi_ref = float(np.angle(z1)) if r1 > 1e-4 else 0.0
            state_type = "Incohérent"

        return psi_ref, r1, r2, r3, state_type

    def _init_physics(self):
        """Initialise les phases selon le mode de cluster sélectionné, les fréquences et le buffer circulaire."""
        self._apply_cluster_phases()

        # Dispersions intrinsèques des fréquences autour de omega_0
        if self.gamma <= 0.0:
            self.delta_omega = np.zeros(self.n)
            self.omega = np.full(self.n, self.omega_0)
        else:
            raw_delta = cauchy.rvs(loc=0.0, scale=self.gamma, size=self.n)
            self.delta_omega = np.clip(raw_delta, -15.0 * self.gamma, 15.0 * self.gamma)
            self.omega = self.omega_0 + self.delta_omega

        # Vitesses instantanées initiales
        self.dphi = np.copy(self.omega)

        # Réseau toujours en Tous-à-tous (couplage global sans auto-couplage)
        self.C = np.ones((self.n, self.n), dtype=np.float64)
        np.fill_diagonal(self.C, 0.0)

        # Buffer circulaire d'historique pour le retard tau (jusqu'à 10*pi s)
        self.max_buf = int(np.ceil(10.0 * np.pi / self.dt)) + 100
        self.history = np.tile(self.phi, (self.max_buf, 1))
        self.ptr = 0

        self.time_history.clear()
        self.r_history.clear()
        self.time = 0.0
        self.last_real_time = None
        self.time_accumulator = 0.0

    def _init_phases_for_state(self):
        """Réinitialise les phases selon le mode de cluster courant."""
        self._apply_cluster_phases()
        self.history = np.tile(self.phi, (self.max_buf, 1))
        self.ptr = 0
        self.dphi = np.copy(self.omega)
        self.time_history.clear()
        self.r_history.clear()
        self.time = 0.0
        self.last_real_time = None
        self.time_accumulator = 0.0

        if hasattr(self, 'scat') and self.scat is not None:
            x = np.cos(self.phi)
            y = np.sin(self.phi)
            self.scat.set_offsets(np.column_stack((x, y)))
            self.scat.set_facecolor(self._get_colors())

    def compute_order_parameter(self):
        """
        Calcule le paramètre d'ordre complexe :
        p = r * exp(i * psi) = (1/N) * sum_j exp(i * phi_j)
        """
        xb = float(np.mean(np.cos(self.phi)))
        yb = float(np.mean(np.sin(self.phi)))
        psi = float(np.arctan2(yb, xb))
        r = float(np.hypot(xb, yb))
        self.r = r
        return r, psi, xb, yb

    def step(self):
        """
        Un pas d'intégration d'Euler du modèle de Kuramoto avec retard et matrice de connectivité :
        dphi_i / dt = omega_i + (K / N) * sum_j C_ij * sin(phi_j(t - tau) - phi_i(t))
        """
        r, psi, xb, yb = self.compute_order_parameter()
        delay_steps = int(round(self.tau / self.dt))

        if delay_steps == 0 and self.n != 90:
            # Traitement rapide champ moyen O(N) pour grand N sans retard
            dphi = self.omega + self.k * r * np.sin(psi - self.phi)
        else:
            # Traitement vectorisé avec matrice de connectivité et retard
            d_idx = (self.ptr - delay_steps) % self.max_buf
            delayed_phi = self.history[d_idx]
            diff = np.sin(delayed_phi[None, :] - self.phi[:, None])
            coupling = np.sum(self.C * diff, axis=1)
            dphi = self.omega + (self.k / self.n) * coupling

        self.dphi = dphi

        # Mise à jour des phases
        self.phi = (self.phi + dphi * self.dt + np.pi) % (2 * np.pi) - np.pi

        # Enregistrement dans le buffer circulaire
        self.ptr = (self.ptr + 1) % self.max_buf
        self.history[self.ptr] = self.phi

        self.time += self.dt
        self.time_history.append(self.time)
        self.r_history.append(r)
        return r, psi, xb, yb

    def _get_zone_name(self, x, y):
        """
        Identifie la zone de stabilité selon Yeung & Strogatz (PRL 1999) :
        x = omega_0 * tau, y = K / omega_0.
        """
        if y > 1.0:
            return "Zone Stable (Synchronie stable pour tout retard)"

        # Vérification langue noire (incohérence stable, synchronie instable)
        for m in range(1, 6):
            y_max_b = 1.0 / (2.0 * (2.0 * m - 1.0))
            if y <= y_max_b:
                x_left = (4.0 * m - 3.0) * np.pi / (2.0 - 2.0 * y)
                x_right = (4.0 * m - 1.0) * np.pi / (2.0 + 2.0 * y)
                if x_left <= x <= x_right:
                    return "Langue Noire (Synchronie instable, incohérence stable)"

        # Vérification langue grise (régime bistable)
        for m in range(1, 6):
            y_max_g = 1.0 / (2.0 * m - 1.0)
            if y <= y_max_g:
                x_left = (4.0 * m - 3.0) * np.pi / (2.0 - y)
                x_right = (4.0 * m - 1.0) * np.pi / (2.0 + y)
                if x_left <= x <= x_right:
                    return "Langue Grise (Bistable : synchronie ou incohérence selon CI)"

        return "Zone Stable (Synchronie stable)"

    def _get_point_size(self):
        if self.n <= 20:
            return 70
        elif self.n <= 60:
            return 50
        elif self.n <= 150:
            return 36
        elif self.n <= 350:
            return 22
        elif self.n <= 700:
            return 14
        else:
            return 8

    def _get_colors(self):
        """
        Calcule les couleurs des oscillateurs selon leur écart à la fréquence moyenne :
        - Plus rouge lorsque la fréquence de l'oscillateur est proche de la fréquence moyenne.
        - Plus bleue lorsqu'elle s'en éloigne.
        """
        mean_freq = float(np.mean(self.dphi)) if len(self.dphi) > 0 else self.omega_0
        diff = np.abs(self.dphi - mean_freq)
        scale = max(0.25, float(np.max(diff)))
        norm = np.clip(1.0 - (diff / scale), 0.0, 1.0)
        return plt.cm.coolwarm(norm)

    def _create_scatter(self):
        colors = self._get_colors()
        size = self._get_point_size()
        return self.ax_circle.scatter(
            np.cos(self.phi),
            np.sin(self.phi),
            c=colors,
            s=size,
            edgecolors='#0f172a' if self.n <= 300 else 'none',
            linewidths=0.6,
            zorder=3
        )

    def _rebuild_scatter(self):
        if hasattr(self, 'scat') and self.scat is not None:
            self.scat.remove()
        self.scat = self._create_scatter()
        self.fig.canvas.draw_idle()

