        self.fig.canvas.mpl_connect('button_release_event', self._on_mouse_release)

        # 4. Panneau d'informations textuel sous les graphiques
        self.ax_info = self.fig.add_axes([0.36, 0.30, 0.61, 0.11], facecolor=self.c_card)
